type Stage<T> = (input: T) => T;

const stages: readonly Stage<Row>[] = [parse, validate, enrich];
const run = (input: Row) => stages.reduce((acc, stage) => stage(acc), input);

async function* enrich(src: AsyncIterable<Row>): AsyncGenerator<Row> {
  for await (const row of src) yield { ...row, crm: await lookup(row.id) };
}

for await (const row of validate(parse(source()))) use(row);
